<?php
declare(strict_types=1);namespace QualitySystem\Services;use PDO;use RuntimeException;use QualitySystem\Domain\CourseReport\CourseReport;use QualitySystem\Domain\CourseReport\CourseReportValidator;use QualitySystem\Repositories\CourseReportRepository;use QualitySystem\Security\AuditLogger;use QualitySystem\Security\PermissionMatrix;
final class CourseReportService{public function __construct(private readonly PDO$pdo,private readonly CourseReportRepository$repo){}public function save(array$i,string$role,int$user,?int$id=null):int{$action=$id===null?'create':'update';if(!PermissionMatrix::allows($role,'course_reports',$action))throw new RuntimeException('Forbidden',403);$existing=$id!==null?$this->repo->findScoped($id,$role,$user):null;if($id!==null&&!$existing)throw new RuntimeException('Course report not found.',404);$specId=($i['course_specification_id']??'')!==''?(int)$i['course_specification_id']:null;if($specId){$spec=$this->repo->specification($specId);if(!$spec)throw new CourseReportValidationException(['Selected course specification does not exist.']);$allowed=array_column($this->repo->courseSpecifications($role,$user),'id');if(!in_array($specId,array_map('intval',$allowed),true))throw new RuntimeException('Forbidden',403);foreach(['course_code','course_title','program_name','department_name','college_name','institution_name']as$f)if(isset($spec[$f]))$i[$f]=$spec[$f];}$errors=CourseReportValidator::validate($i);if($errors)throw new CourseReportValidationException($errors);$f=[];foreach(CourseReportRepository::EDITABLE as$x){$v=trim((string)($i[$x]??''));$f[$x]=$v===''?null:$v;}foreach(['students_enrolled','students_passed','students_failed']as$x)$f[$x]=$f[$x]===null?0:(int)$f[$x];foreach(['students_starting','students_completed','course_specification_id']as$x)$f[$x]=$f[$x]===null?null:(int)$f[$x];$f['created_by_user_id']=$id===null?$user:($existing['created_by_user_id']??null);$this->pdo->beginTransaction();try{$saved=$this->repo->save(new CourseReport($id,$f));AuditLogger::record($this->pdo,'course_report_'.$action,'allowed','Course Reports',[],'course_report',$saved);$this->pdo->commit();return$saved;}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}public function delete(int$id,string$role,int$user):void{if(!PermissionMatrix::allows($role,'course_reports','delete'))throw new RuntimeException('Forbidden',403);if(!$this->repo->findScoped($id,$role,$user))throw new RuntimeException('Course report not found.',404);$this->pdo->beginTransaction();try{$this->repo->delete($id);AuditLogger::record($this->pdo,'course_report_delete','allowed','Course Reports',[],'course_report',$id);$this->pdo->commit();}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}}
final class CourseReportValidationException extends RuntimeException{public function __construct(public readonly array$errors){parent::__construct('Validation failed.',422);}}
